arguments.argument:
var c_check;
c_check=0

if click=1
{
    with(obj_unit)
    {
        if global.player_control=player and sk_drag_check(global.drag_x, global.drag_y, mouse_x, mouse_y) and drag_ok=1
        {
            if !c_check
            {
                for(i=0; i!=other.vab_unit; i+=1){if instance_number(other.vab_unit_id[i]){other.vab_unit_id[i].click_check=0}}
                other.vab_unit=0
                c_check=1
            }
            click_check=1
            other.vab_unit_id[other.vab_unit]=id
            other.vab_unit+=1
            if other.vab_unit>7{break}
        }
    }
    click=0
}
